import{_ as t,a as o,b as a,c as n}from"./chunks/solar-solo-ports.BXO9gIDw.js";import{_ as r,o as s,c as i,a3 as l}from"./chunks/framework.BlfGB29P.js";const w=JSON.parse('{"title":"Solar – inverters and stackable batteries","description":"Neutral SVG modules with flush housing snap points, plain-text readings and configurable data-flow ports.","frontmatter":{"title":"Solar – inverters and stackable batteries","description":"Neutral SVG modules with flush housing snap points, plain-text readings and configurable data-flow ports."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/solar.md","filePath":"en/projects/grafik-visual-studio/solar.md","lastUpdated":1792850658000}'),p={name:"en/projects/grafik-visual-studio/solar.md"};function d(h,e,g,u,c,m){return s(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="solar" tabindex="-1">Solar <a class="header-anchor" href="#solar" aria-label="Permalink to &quot;Solar&quot;">​</a></h1><p><strong>Solar 0.1.3</strong> requires <strong>Studio 0.1.280 or later</strong>. This separate widget set contains four manufacturer-independent modules with transparent SVG graphics. Update Studio first, then import <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/refs/heads/master/ha_grafik_visual_studio/packages/solar/ugso.solar.wg" target="_blank" rel="noreferrer">ugso.solar.wg</a> through the package settings.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Default size</th><th>Housing snap points</th><th>Line ports</th></tr></thead><tbody><tr><td>Stack inverter head</td><td>256 × 64 px</td><td>Bottom center</td><td>Left/right plus two PV inputs on each enclosure side</td></tr><tr><td>Battery module</td><td>256 × 169 px</td><td>Top and bottom center</td><td>Left, right</td></tr><tr><td>Standalone inverter</td><td>144 × 103.3 px</td><td>None</td><td>Left/right/top center plus seven bottom ports including corners</td></tr><tr><td>Solar panel with base</td><td>320 × 288 px</td><td>None</td><td>One output: pole or left/right widget edge</td></tr></tbody></table><p>The head graphic is centered and touches the bottom widget edge. The battery graphic touches both top and bottom edges. Battery and standalone inverter preserve their proportions when resized. The visible standalone enclosure is about one-third narrower than the head.</p><p><img src="'+t+'" alt="Solar in the editor: battery stack, standalone inverter and both solar panel orientations"></p><p>Example with preview readings and visible connection points. Yellow circles are inputs, blue circles are outputs and purple squares are housing snap points. Points disappear in runtime.</p><h2 id="solar-panel-with-pole-and-base" tabindex="-1">Solar panel with pole and base <a class="header-anchor" href="#solar-panel-with-pole-and-base" aria-label="Permalink to &quot;Solar panel with pole and base&quot;">​</a></h2><p>Use <strong>Solar module → Orientation</strong> to choose <strong>Original</strong> or <strong>Mirrored</strong>. Only the SVG graphic flips horizontally; text remains readable. Resizing preserves proportions.</p><p><img src="'+o+'" alt="Solar panels with poles and bases: original on the left, mirrored on the right, both outputs at the pole"></p><p>Select a Home Assistant entity under <strong>Power → Input entity (power)</strong>. Values in kW are converted to W. <strong>Show reading</strong> hides only the unframed text; the output keeps forwarding data. Without an entity, the preview value applies; unavailable entity values appear as a dash.</p><p>Under <strong>Line port → Output point position</strong>, choose <strong>At the pole above the base</strong>, <strong>Left widget edge</strong> or <strong>Right widget edge</strong>. Edge positions use the same height as the pole point. There is always just one output; existing SVG lines follow position changes automatically. <strong>Enable output point</strong> turns it off or on. In runtime, the point disappears while the SVG line remains visible. The panel has no housing snap points.</p><h2 id="assemble-a-stack" tabindex="-1">Assemble a stack <a class="header-anchor" href="#assemble-a-stack" aria-label="Permalink to &quot;Assemble a stack&quot;">​</a></h2><p>Add <strong>one head</strong> and <strong>1–6 instances of the same battery widget</strong>, depending on the installation. Each battery has its own settings and entities. Center housing snap points are enabled by default with a <strong>0 px</strong> gap. Drag a battery&#39;s top point near the bottom point of the head or another battery; the modules snap flush and centered.</p><p>Use <strong>Housing snap points</strong> to configure snapping, individual points, spacing and persistent editor markers. Housing points affect placement only and carry no values. They disappear in runtime.</p><h2 id="plain-text-readings-on-the-enclosure" tabindex="-1">Plain-text readings on the enclosure <a class="header-anchor" href="#plain-text-readings-on-the-enclosure" aria-label="Permalink to &quot;Plain-text readings on the enclosure&quot;">​</a></h2><p><strong>Power</strong>, <strong>Temperature</strong> and <strong>State of charge (SoC)</strong> each provide a Home Assistant entity picker and preview value. Units are <strong>W</strong>, <strong>°C</strong> and <strong>%</strong>. Power from a kW entity is converted to W. Preview values apply only when no entity is assigned. Missing or unknown states appear as <strong>—</strong>.</p><p><strong>Show reading</strong> hides only that text display. The entity continues updating and outputs still provide its value. Battery readings start immediately below the first-third seam and stack vertically without blank rows for hidden readings. There are no frames or display boxes. The order is power, temperature, SoC. Text color and maximum font size are configurable; text shrinks when space is limited.</p><p>By default, the battery shows all three readings and the standalone inverter shows power only. The head has no readings or settings groups for power, temperature, SoC or power direction. The standalone inverter retains these settings.</p><p>For batteries, <strong>Power</strong>, <strong>Temperature</strong> and <strong>State of charge (SoC)</strong> each provide a separate <strong>Reading text color</strong>. Until a separate color is set, the general text color applies. Colors persist when readings are hidden and shown again.</p><p><img src="'+a+'" alt="Stack head with four PV inputs and a battery with colored readings and side ports at the lower seam"></p><p>Under <strong>Power direction</strong>, enable an optional direction symbol. Select whether positive power means <strong>Energy in</strong> or <strong>Energy out</strong>, and enter both symbols as text. No symbol appears for zero or an unknown value. The displayed number retains its sign.</p><h2 id="svg-line-inputs-and-outputs" tabindex="-1">SVG line inputs and outputs <a class="header-anchor" href="#svg-line-inputs-and-outputs" aria-label="Permalink to &quot;SVG line inputs and outputs&quot;">​</a></h2><p>The <strong>standalone inverter</strong> provides seven evenly spaced bottom line ports: both corners, the existing center and two additional points on either side of the center. Together with the left/right/top center ports, ten ports are available. Under <strong>Line ports</strong>, choose <strong>Off</strong>, <strong>Input</strong> or <strong>Output</strong> and a value for each point. The six new bottom ports start disabled; existing ports and connections remain unchanged.</p><p><img src="'+n+'" alt="Standalone inverter with seven bottom line ports and three more ports at the left, right and top"></p><p>All ten points are enabled as outputs in this example; each point&#39;s role is configurable in your project.</p><p>Battery left and right ports each offer a <strong>Position</strong>: <strong>Widget edge center</strong> or <strong>Enclosure edge at lower seam</strong>. Set each side independently. Existing connections follow automatically; roles and value assignments remain unchanged. This does not affect the top/bottom center housing snap points used for stacking.</p><p>The head has four visible PV input sockets: upper/lower left and upper/lower right. All four start enabled and can be disabled separately under <strong>Line ports</strong>. They follow the bottom-aligned graphic even if widget height changes. Connect a solar panel&#39;s SVG line to one of these sockets. They are separate line destinations without automatic value summation. The former top line port is removed; existing left/right ports remain available.</p><p>Under <strong>Line ports</strong>, each available side has two settings:</p><ul><li><strong>Role:</strong> Off, Input or Output. Line ports are off by default.</li><li><strong>Value:</strong> Power, Temperature or State of charge (SoC).</li></ul><p>An <strong>output</strong> forwards the chosen value and unit to Number or an SVG line. An <strong>input</strong> receives that value from exactly one connected source, replacing the entity for that channel. Use at most one input per value. Another output can forward the received value; feedback loops are detected. Home Assistant entities are never written.</p><p>Line ports are independent of housing snap points. Active outputs use the Studio output-point color. Ports disappear in runtime; ordinary SVG lines remain visible, while Value connections stay hidden.</p><p>All standard CSS groups are available; optional groups start disabled. Custom padding or borders can affect flush alignment.</p><p>The SVGs are original UGSo artwork without manufacturer logos. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/solar" target="_blank" rel="noreferrer">Source, build instructions and MIT license</a>.</p>',33)])])}const v=r(p,[["render",d]]);export{w as __pageData,v as default};
